--
-- discourse-routines-install.sql: the synthetic routine set of the discourse sample.
-- Generated by scripts/render_sample_routines.py from discourse-routines.json.
-- Do not edit by hand: change the JSON set and render again.
-- Run it on the sample's PostgreSQL source, in the `discourse` database.
--
-- Run it with psql as a user that may give its routines to the roles discourse, postgres,
-- the owners the set records. posts_bump_topic() is owned by discourse, so the run
-- shows its owner rewrite. The tables it reads must exist: run it after the sample's
-- schema is loaded. Once installed, the trigger sets a topic's bumped_at on each new
-- post. Remove the set with the remove script. It runs in one transaction and can
-- run again.

\set ON_ERROR_STOP on
BEGIN;

-- function public.topic_visible_post_count
CREATE OR REPLACE FUNCTION public.topic_visible_post_count(p_topic_id integer)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  SELECT count(*)::integer FROM public.posts
   WHERE topic_id = p_topic_id AND deleted_at IS NULL
$function$;
ALTER FUNCTION public.topic_visible_post_count(p_topic_id integer) OWNER TO postgres;

-- function public.posts_bump_topic
CREATE OR REPLACE FUNCTION public.posts_bump_topic()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.topics SET bumped_at = NEW.created_at
   WHERE id = NEW.topic_id AND bumped_at < NEW.created_at;
  RETURN NEW;
END;
$function$;
ALTER FUNCTION public.posts_bump_topic() OWNER TO discourse;

-- procedure public.prune_read_notifications
CREATE OR REPLACE PROCEDURE public.prune_read_notifications(IN p_days integer)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
  DELETE FROM public.notifications
   WHERE read AND created_at < now() - make_interval(days => p_days);
END;
$procedure$;
ALTER PROCEDURE public.prune_read_notifications(IN p_days integer) OWNER TO postgres;

-- procedure public.begin_upload_snapshot
CREATE OR REPLACE PROCEDURE public.begin_upload_snapshot(IN p_label text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
  PERFORM pg_backup_start(p_label, true);
END;
$procedure$;
ALTER PROCEDURE public.begin_upload_snapshot(IN p_label text) OWNER TO postgres;

-- trigger public.posts_bump_topic
DROP TRIGGER IF EXISTS posts_bump_topic ON public.posts;
CREATE TRIGGER posts_bump_topic AFTER INSERT ON public.posts FOR EACH ROW EXECUTE FUNCTION posts_bump_topic();

COMMIT;
